package cn.fuzhu.toolkit.modules;
import cn.fuzhu.toolkit.FuzhuToolkitPlugin; import cn.fuzhu.toolkit.module.AbstractModule; import org.bukkit.command.*; import org.bukkit.entity.Player;
public class WeatherModule extends AbstractModule {public WeatherModule(FuzhuToolkitPlugin p){super(p);config=p.moduleConfig(id());}public String id(){return "Weather";}public String description(){return "/weather sun|rain|storm 设置天气";}public boolean handle(CommandSender s,String l,String[] a){if(!s.hasPermission("fuzhu.admin")){plugin.msg(s,"&c你没有权限。");return true;}Player p=ModuleUtil.player(plugin,s);if(p==null)return true;if(a.length==0){plugin.msg(s,"&e/weather sun|rain|storm");return true;}String x=a[0].toLowerCase();if(x.equals("sun")){p.getWorld().setStorm(false);p.getWorld().setThundering(false);}else if(x.equals("rain")){p.getWorld().setStorm(true);p.getWorld().setThundering(false);}else if(x.equals("storm")){p.getWorld().setStorm(true);p.getWorld().setThundering(true);}else {plugin.msg(s,"&c未知天气。");return true;}plugin.broadcast("&b天气已设置为 &f"+x);return true;}}
